const runnerBase = process.env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = process.env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const payload = $json.body ?? $json;
const pr = payload.pull_request || {};
const prNumber = pr.number || payload.number;
const title = pr.title || 'Untitled PR';
const body = pr.body || '';
const changedFiles = pr.changed_files || 0;
const additions = pr.additions || 0;
const deletions = pr.deletions || 0;
const risk = changedFiles > 20 || additions + deletions > 800 ? 'high' : changedFiles > 8 || additions + deletions > 250 ? 'medium' : 'low';
const prompt = [
  'You are producing a concise first-pass PR review comment.',
  'Use exactly these sections: First Pass Summary, Risks, Suggested Checks.',
  'Keep it under 220 words.',
  '',
  `Title: ${title}`,
  `Changed files: ${changedFiles}`,
  `Additions: ${additions}`,
  `Deletions: ${deletions}`,
  '',
  'Body:',
  body || 'No PR body provided.',
].join('\n');

let reviewComment = `## First Pass Summary\n\n- Risk level: ${risk}\n- Files changed: ${changedFiles}\n- Diff size: +${additions} / -${deletions}\n\n## Risks\n\n- Verify the PR description matches the actual blast radius.\n- Confirm tests or manual validation cover the changed area.\n\n## Suggested Checks\n\n- Re-read touched workflows and scripts for integration drift.\n- Confirm durable reports and context updates still land correctly.`;
try {
  const ollamaResponse = await fetch('http://host.docker.internal:11434/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'qwen3:8b', prompt, stream: false }),
  });
  if (ollamaResponse.ok) {
    const ollamaJson = await ollamaResponse.json();
    reviewComment = (ollamaJson.response || '').trim() || reviewComment;
  }
} catch {}

const reportRelativePath = `pr-first-pass/${new Date().toISOString().replace(/[:]/g, '-')}-pr-${prNumber || 'unknown'}.md`;
const commentRelativePath = `pr-first-pass/${new Date().toISOString().replace(/[:]/g, '-')}-pr-${prNumber || 'unknown'}-comment.md`;
for (const item of [
  { relativePath: reportRelativePath, content: ['# PR Review First Pass', '', reviewComment].join('\n') },
  { relativePath: commentRelativePath, content: reviewComment },
]) {
  const writeResponse = await fetch(`${runnerBase}/reports/write`, {
    method: 'POST',
    headers,
    body: JSON.stringify(item),
  });
  if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);
}

let commentResult = null;
if (prNumber) {
  const commentResponse = await fetch(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action: 'github_pr_comment', mode: 'sync', args: [String(prNumber), `docs/automation/${commentRelativePath}`] }),
  });
  const rawComment = await commentResponse.text();
  commentResult = rawComment ? JSON.parse(rawComment) : null;
}

return [{ json: { prNumber, risk, reportRelativePath, commentRelativePath, commentResult } }];
